/* Typed-state port of uha04_dec4.c - generated by tools/port_to_typed.py.
 *
 * The model state that lives outside the loaded image now sits in
 * typed struct members; the cells inside the image and the model
 * tables (addressed through computed arena offsets) still use the
 * arena.
 *
 * The file is maintained by hand on top of the generated version: the
 * D4V_* accessor overrides that keep the arena cells in the arena, the
 * per-block model pointers in the context and the PPM order table are
 * all hand-written, and re-running tools/port_to_typed.py would drop
 * them.  See DEC4_CLEAN_PLAN.md.
 */
/* UHARC 0.4 decompressor core 4 (methods 24..39) - portable C89 port.
 *
 * Ported from the UHARC04.lst disassembly of the UHARC 0.4 BETA decoder
 * (control flow and constants come straight from the listing).
 *
 * Original -> port mapping (UHARC04.lst):
 *   sub_415130 (per-file init)     -> UhaDec4_04Init
 *   sub_415980 (teardown)          -> UhaDec4_04Free
 *   sub_41CE30 (block driver)      -> d4v_block
 *   sub_41CD30 (range coder)       -> d4vc_rc
 *   sub_418830 (per-symbol PPM)    -> d4vc_sym
 *   sub_41AF70 (escape/long-match) -> d4v_escape
 *   sub_4177A0 (mask/order sel)    -> d4v_ctxsel
 *   sub_417E10 (PPM decoder)       -> d4vc_ppmdec
 *   sub_415C40 (LZP/literal path)  -> d4vc_lzp
 *   sub_416220 (PPM path)          -> d4vc_ppm
 *   sub_41C190 (model emit)        -> d4v_emit
 *   sub_41C670 (context hash)      -> d4v_hash
 *   sub_426EE0 (price prefix sums) -> d4vc_prices
 *   sub_40D070 (heap alloc)        -> d4vc_alloc (bump over one calloc block)
 *   sub_40D570 (fill, replicated)  -> memset equivalent
 *   sub_425810 (u16 fill)          -> d4vc_fill16
 *   sub_40DA80 (heap base query)   -> arena base
 *
 * Memory model: the original allocates ~20 heap blocks via sub_40D070 and
 * addresses everything (including DGROUP globals) by absolute address.
 * The port keeps one zeroed arena; every original absolute address is used
 * as an arena offset (V4O clamps like the 0.6 port's D4O). Block pointers
 * (dword_433B40..) are arena offsets handed out by a bump allocator in the
 * same order and sizes as the original.
 *
 * Register convention: x86 partial-register writes (mov al/dl, [mem] etc.)
 * preserve the other lanes, whose values the original code inherits from
 * whatever the caller left behind. The C port models each register as an
 * unsigned variable, so every worker auto is explicitly zero-initialised
 * at declaration; without this the build reads indeterminate stack garbage
 * (non-deterministic output) where the original reads deterministic
 * leftovers (in practice zero, e.g. xor-cleared lanes).
 */
#include <stdlib.h>
#include <string.h>
#include "UhaDec4.h"
#ifndef _MSC_VER
#ifndef UHI64
#define UHI64 unsigned long long
#endif
#else
#ifndef UHI64
#define UHI64 unsigned __int64
#endif
#endif
#ifndef uharc_dec_read_cb
typedef Uha4ReadCb uharc_dec_read_cb;
typedef Uha4WriteCb uharc_dec_write_cb;
#endif

extern "C" const unsigned char d4v_dgroup[73728];
#include "uha04_dec4_addr.h"
#include "uha04_dec4_state.h"
#include <stddef.h>

/* The globals are one byte array in the typed state: the DGROUP image
 * (0x42E000..0x440000) and the BSS above it (0x440000..0x45D0C8).  The
 * image is copied into it at init, so a cell inside the image keeps its
 * initial value from the image and a cell in the BSS starts at zero -
 * which is what the arena held. */

#define D4V_FIXED_BASE   0x420000UL
#define D4V_FIXED_SIZE   0x40000UL   /* ..0x460000 covers DGROUP/BSS/named cells */
#define D4V_GLOBALS_BASE 0x42E000UL /* the DGROUP image */
#define D4V_GLOBALS_END  0x45D0C8UL /* end of the last named cell */
#define D4V_IO_BASE    0x00000000UL
#define D4V_IO_SIZE    0x00040000UL /* covers in_buf/out_buf carved near 0x1000 */
#define D4V_MODEL_BASE 0x00600000UL
#define D4V_MODEL_SIZE 0x04000000UL /* 64MB for ~53MB carved footprint */

typedef struct dec4v_ctx {
    unsigned char *mem; /* compat, unused */
    unsigned char fx_gap[8]; /* the arena's zero gap past the fixed region */
    unsigned char *io_mem;
    unsigned char *model_mem;
    unsigned long hi;
    uharc_dec_read_cb rcb;
    void *rctx;
    uharc_dec_write_cb wcb;
    void *wctx;
    unsigned in_pos;
    unsigned in_avail;
    unsigned out_fill;
    unsigned long out_tot;
    unsigned long out_len;
    int err;
    /* arena offsets of the 64KB stream buffers (dword_436ED0/436ED4) */
    unsigned long in_buf;
    unsigned long out_buf;
    /* per-block pointers (aliases into model_mem) and bases */
    /* blk00_dict/blk00_base: MODEL-REGION alias, not just the dict block.
     * c->hi is set to D4V_MODEL_BASE before the model blocks are carved and
     * the dict block is the FIRST carve, so blk00_base == D4V_MODEL_BASE
     * and blk00_dict == model_mem.  Hence
     *     blk00_dict[X - blk00_base] == model_mem[X - MODEL_BASE]
     *     == d4v_ptr(c, X)
     * for every model-region address X.  A blk00_dict[...] access whose
     * address comes from another block pointer (BLK_PTR_03/04/05/...)
     * therefore RESOLVES CORRECTLY but is misattributed; such sites use
     * the owning block pointer (c->blkNN) instead.  Every blk00_dict
     * access has been checked to land inside the model region. */
    unsigned char *blk00_dict; unsigned long blk00_base; unsigned long blk00_size;
    unsigned char *blk01; unsigned long blk01_base; unsigned long blk01_size;
    unsigned char *blk02; unsigned long blk02_base; unsigned long blk02_size;
    unsigned char *blk03; unsigned long blk03_base; unsigned long blk03_size;
    unsigned char *blk04; unsigned long blk04_base; unsigned long blk04_size;
    unsigned char *blk05; unsigned long blk05_base; unsigned long blk05_size;
    unsigned char *blk06; unsigned long blk06_base; unsigned long blk06_size;
    unsigned char *blk07; unsigned long blk07_base; unsigned long blk07_size;
    unsigned char *blk08; unsigned long blk08_base; unsigned long blk08_size;
    unsigned char *blk09; unsigned long blk09_base; unsigned long blk09_size;
    unsigned char *blk10; unsigned long blk10_base; unsigned long blk10_size;
    unsigned char *blk11; unsigned long blk11_base; unsigned long blk11_size;
    unsigned char *blk12; unsigned long blk12_base; unsigned long blk12_size;
    unsigned char *blk13; unsigned long blk13_base; unsigned long blk13_size;
    unsigned char *blk14; unsigned long blk14_base; unsigned long blk14_size;
    unsigned char *blk15; unsigned long blk15_base; unsigned long blk15_size;
    unsigned char *blk16; unsigned long blk16_base; unsigned long blk16_size;
    unsigned char *blk17; unsigned long blk17_base; unsigned long blk17_size;
    unsigned char *blk18; unsigned long blk18_base; unsigned long blk18_size;
    unsigned char *blk19; unsigned long blk19_base; unsigned long blk19_size;
    /* PPM per-order context blocks.  The original addresses the eight PPM
     * orders through the stride-4 cell run 0x433B58..0x433B74, which is
     * exactly the contiguous block-pointer array BLK_PTR_06..BLK_PTR_13;
     * order o therefore owns model block 06+o, and dword_459E38[o*4] is
     * the 4-byte slot index inside that block.  blkord[o] is that block's
     * typed pointer and blkord_base[o] its arena base address (the PPM
     * scorer hands that address to its caller, so it is still needed).
     * Verified over the whole core-4 corpus: the cell value always equals
     * the block base and the slot index always stays inside the block.
     *
     * The slot index itself is read through D4V_TBL_459E38_32, which is
     * still overridden to d4v_ptr(): the eight slots 0x459E38..0x459E54
     * carry two overlapping 16-bit hi-word views (0x459E3E, 0x459E42) and
     * therefore need a union, not eight struct members, before the
     * overrides can go. */
    unsigned char *blkord[8];
    unsigned long blkord_base[8];
    d4v_state st;   /* typed model state */
    /* The raw accesses read and write dwords straight into the globals
     * array, so a dword at its very last byte would run past it.  The
     * pad takes that read; the arena's bytes there are zero, and so
     * are these. */
    unsigned char fx_pad[8];
} dec4v_ctx;

/* The arena port reaches every cell through M8/M16/M32, which clamp the
 * address to the end of its 64 MB buffer (V4O).  The address itself is
 * computed in 32 bits, so an index that runs past the globals wraps
 * back into the arena - and into the model blocks, which hold live
 * data.  The typed port has to wrap and clamp the same way to read the
 * same bytes; c->fx_gap stands in for the arena's zero gap. */
static unsigned char *d4v_fx(dec4v_ctx *c, unsigned long off)
{
    /* off is relative to D4V_FIXED_BASE.  The arena computes the
     * address in 32 bits (the macro casts the offset to unsigned) and
     * clamps it at V4_ARENA-8, so an index that runs past the globals
     * wraps back into the arena - and into the model blocks, which hold
     * live data.  The port has to wrap the same way to read the same
     * bytes. */
    unsigned long addr = (D4V_FIXED_BASE + off) & 0xFFFFFFFFUL;
    if (addr > (0x04000000UL - 8UL))
        return c->fx_gap; /* the arena's tail is zero */
    if (addr >= D4V_GLOBALS_BASE && addr < D4V_GLOBALS_END)
        return c->st.fx_42E000 + (addr - D4V_GLOBALS_BASE);
    if (addr >= D4V_MODEL_BASE && addr < D4V_MODEL_BASE + D4V_MODEL_SIZE)
        return c->model_mem + (addr - D4V_MODEL_BASE);
    if (addr < D4V_IO_SIZE)
        return c->io_mem + addr;
    return c->fx_gap;
}

static unsigned char *d4v_ptr(dec4v_ctx *c, unsigned long addr)
{
    if (addr >= D4V_MODEL_BASE && addr < D4V_MODEL_BASE + D4V_MODEL_SIZE)
        return c->model_mem + (addr - D4V_MODEL_BASE);
    /* The globals are one byte array the typed state owns. */
    if (addr >= D4V_GLOBALS_BASE && addr < D4V_GLOBALS_END)
        return c->st.fx_42E000 + (addr - D4V_GLOBALS_BASE);
    if (addr < D4V_IO_SIZE)
        return c->io_mem + addr;
    /* The arena port clamps every address to the end of its buffer, so
     * an address outside the globals, the I/O buffers and the model
     * blocks reads the arena's zero gap.  fx_gap stands in for it. */
    return c->fx_gap;
}

/* Boundary-safe byte-wise accessors: the fixed region is stored in more
 * than one allocation, so a multi-byte access may straddle the boundary
 * between them and must not read a contiguous block of memory. */
static unsigned int d4v_ld8(dec4v_ctx *c, unsigned long a)
{
    return *d4v_ptr(c, a);
}
static void d4v_st8(dec4v_ctx *c, unsigned long a, unsigned int v)
{
    *d4v_ptr(c, a) = (unsigned char)v;
}
static unsigned int d4v_ld16(dec4v_ctx *c, unsigned long a)
{
    return (unsigned int)(*d4v_ptr(c, a)
        | ((unsigned int)*d4v_ptr(c, a + 1UL) << 8));
}
static void d4v_st16(dec4v_ctx *c, unsigned long a, unsigned int v)
{
    *d4v_ptr(c, a) = (unsigned char)(v & 0xFFU);
    *d4v_ptr(c, a + 1UL) = (unsigned char)((v >> 8) & 0xFFU);
}
static unsigned int d4v_ld32(dec4v_ctx *c, unsigned long a)
{
    return (unsigned int)(*d4v_ptr(c, a)
        | ((unsigned int)*d4v_ptr(c, a + 1UL) << 8)
        | ((unsigned int)*d4v_ptr(c, a + 2UL) << 16)
        | ((unsigned int)*d4v_ptr(c, a + 3UL) << 24));
}
static void d4v_st32(dec4v_ctx *c, unsigned long a, unsigned int v)
{
    *d4v_ptr(c, a) = (unsigned char)(v & 0xFFU);
    *d4v_ptr(c, a + 1UL) = (unsigned char)((v >> 8) & 0xFFU);
    *d4v_ptr(c, a + 2UL) = (unsigned char)((v >> 16) & 0xFFU);
    *d4v_ptr(c, a + 3UL) = (unsigned char)((v >> 24) & 0xFFU);
}

/* Little-endian u32 read from a lifted const table.  The rep movsd copies
 * at 0x416515/0x41659F used to read the image through d4v_ptr; the source
 * is a read-only table, so the index goes straight into the array. */
static unsigned int d4v_tbl_ld32(const unsigned char *t, unsigned long i)
{
    return (unsigned int)t[i]
        | ((unsigned int)t[i + 1] << 8)
        | ((unsigned int)t[i + 2] << 16)
        | ((unsigned int)t[i + 3] << 24);
}

/* sub_40D070: bump allocator over the arena (the original manages a real
 * heap with freelists; sizes/aligns below mirror the init sequence). */
unsigned long d4vc_alloc(dec4v_ctx *c, unsigned long size)
{
    unsigned long p;
    if (size == 0) return 0;
    p = (c->hi + 15UL) & ~15UL;
    /* segmented regions */
    c->hi = p + size;
    return p;
}

/* sub_425810(t1=count, t3=dst, t0=val): fill count u16 with val. */
void d4vc_fill16(dec4v_ctx *c, unsigned int count, unsigned int dst,
                       unsigned int val)
{
    unsigned int i;
    for (i = 0; i < count; i++)
        d4v_st16(c, (unsigned long)(dst + 2 * i), (unsigned short)val);
}

